// ================= SAFE INIT =================
document.addEventListener('DOMContentLoaded', () => {

    /*
     * Find the navigation map element.
     *
     * If the page does not contain the map, stop execution
     * instead of allowing the rest of the script to crash.
     */
    const mapEl = document.getElementById('navMap');

    if (!mapEl) return;


    // ================= DESTINATION DATA =================

    /*
     * Read the destination coordinates from the HTML data
     * attributes generated by Blade.
     */
    const lat = Number(mapEl.dataset.lat);
    const lng = Number(mapEl.dataset.lng);
    const name = mapEl.dataset.name;


    /*
     * Coordinates are required for routing.
     *
     * Stop if either value is invalid.
     */
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
        console.error('Invalid agency coordinates.');
        return;
    }


    // ================= ICONS =================

    /*
     * Create the user's location marker.
     *
     * The actual visual appearance is controlled by CSS.
     */
    const userIcon = L.divIcon({
    className: '',
    html: '<div class="user-marker"></div>',
    iconSize: [14, 14]
});


    /*
     * Create the destination marker.
     */
    const destIcon = L.divIcon({
    className: '',
    html: '<div class="dest-marker"></div>',
    iconSize: [20, 20],
    iconAnchor: [10, 10]
});


    // ================= MAP =================

    /*
     * Initialize Leaflet.
     *
     * Zoom controls are disabled because the navigation
     * interface currently uses the available screen space
     * for the map itself.
     */
    const navMap = L.map('navMap', {
        zoomControl: false
    }).setView([lat, lng], 16);


    /*
     * Load OpenStreetMap tiles.
     */
    L.tileLayer(
        'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
        {
            maxZoom: 19,
            attribution: '&copy; OpenStreetMap contributors'
        }
    ).addTo(navMap);


    // ================= DESTINATION =================

    /*
     * Place the agency's destination marker.
     */
    L.marker(
        [lat, lng],
        { icon: destIcon }
    ).addTo(navMap);


    /*
 * Keep a reference to the destination label.
 *
 * We need this reference because its position will
 * be recalculated whenever the route changes.
 */
const destinationTooltip = L.tooltip({
    permanent: true,
    direction: 'top',
    offset: [0, -18],
    className: 'dest-tooltip'
})
.setContent(name)
.setLatLng([lat, lng])
.addTo(navMap);

// ================= DESTINATION LABEL COLLISION =================

/*
 * Store the latest route coordinates.
 *
 * Leaflet Routing Machine provides the route as an
 * array of geographic coordinates.
 */
let currentRouteCoordinates = [];


/*
 * Check whether two rectangles overlap.
 *
 * We use this for the tooltip and the projected
 * route segments.
 */
function rectanglesOverlap(a, b) {

    return !(
        a.right < b.left ||
        a.left > b.right ||
        a.bottom < b.top ||
        a.top > b.bottom
    );

}


/*
 * Calculate the bounding rectangle of a line segment.
 *
 * The small padding makes the collision detection
 * slightly more conservative because the purple
 * route itself has visible thickness.
 */
function getSegmentBounds(pointA, pointB, padding = 5) {

    return {

        left:
            Math.min(pointA.x, pointB.x) - padding,

        right:
            Math.max(pointA.x, pointB.x) + padding,

        top:
            Math.min(pointA.y, pointB.y) - padding,

        bottom:
            Math.max(pointA.y, pointB.y) + padding

    };

}


/*
 * Determine whether the tooltip overlaps any
 * visible section of the current route.
 */
function tooltipBlocksRoute(tooltipElement) {

    /*
     * There is no route to collide with yet.
     */
    if (
        !tooltipElement ||
        currentRouteCoordinates.length < 2
    ) {
        return false;
    }


    /*
     * Get the tooltip's position relative to
     * the browser viewport.
     */
    const tooltipRect =
        tooltipElement.getBoundingClientRect();


    /*
     * Get the map's position relative to
     * the browser viewport.
     */
    const mapRect =
        navMap.getContainer().getBoundingClientRect();


    /*
     * Convert the tooltip rectangle into
     * coordinates relative to the Leaflet map.
     */
    const tooltipMapRect = {

        left:
            tooltipRect.left - mapRect.left,

        right:
            tooltipRect.right - mapRect.left,

        top:
            tooltipRect.top - mapRect.top,

        bottom:
            tooltipRect.bottom - mapRect.top

    };


    /*
     * Convert every route coordinate from
     * latitude/longitude into screen coordinates.
     */
    const routePoints =
        currentRouteCoordinates.map(
            coordinate =>
                navMap.latLngToContainerPoint(
                    coordinate
                )
        );


    /*
     * Compare every route segment against
     * the tooltip's bounding rectangle.
     */
    for (
        let i = 0;
        i < routePoints.length - 1;
        i++
    ) {

        const segmentBounds =
            getSegmentBounds(
                routePoints[i],
                routePoints[i + 1]
            );


        /*
         * If a route segment's bounding box
         * intersects the tooltip, consider it
         * a collision.
         */
        if (
            rectanglesOverlap(
                tooltipMapRect,
                segmentBounds
            )
        ) {

            return true;

        }

    }


    /*
     * No route segment intersects the label.
     */
    return false;

}


/*
 * Try several positions around the destination.
 *
 * The positions are ordered so the label normally
 * prefers the familiar position above the marker.
 */
function repositionDestinationLabel() {

    if (!destinationTooltip) {
        return;
    }


    /*
     * Find the actual tooltip DOM element.
     */
    const tooltipElement =
        destinationTooltip.getElement();


    /*
     * Leaflet may not have created the element yet.
     */
    if (!tooltipElement) {
        return;
    }


    /*
     * Candidate positions around the marker.
     *
     * Each candidate contains:
     *
     * direction → which side of the marker
     * offset    → distance from the marker
     */
    const positions = [

    {
        direction: 'top',
        offset: [0, -18]
    },

    {
        direction: 'right',
        offset: [18, 0]
    },

    {
        direction: 'bottom',
        offset: [0, 18]
    },

    {
        direction: 'left',
        offset: [-18, 0]
    }

];


    /*
     * Test each candidate until we find one
     * that doesn't overlap the route.
     */
    for (const position of positions) {

        /*
         * Tell Leaflet which side of the marker
         * the tooltip should use.
         */
        destinationTooltip.options.direction =
            position.direction;


        /*
         * Tell Leaflet how far to offset the label.
         */
        destinationTooltip.options.offset =
            position.offset;


        /*
         * Force Leaflet to recalculate the
         * tooltip's screen position.
         */
        destinationTooltip.update();


        /*
         * If this position doesn't cover the route,
         * keep it and stop searching.
         */
        if (
            !tooltipBlocksRoute(
                tooltipElement
            )
        ) {

            return;

        }

    }


    /*
     * If every candidate technically intersects
     * the route, keep the normal top position.
     *
     * This is a safe fallback rather than leaving
     * the tooltip in an unpredictable position.
     */
    destinationTooltip.options.direction =
        'top';

    destinationTooltip.options.offset =
        [0, -18];

    destinationTooltip.update();

}


    // ================= ROUTING STATE =================

    /*
     * The routing control is created only once.
     *
     * Later, transportation mode can use this same
     * routing layer instead of creating multiple controls.
     */
    let routingControl = null;

    /*
 * The transportation mode currently controlling
 * the detailed route.
 *
 * Car is the default because it is the most familiar
 * navigation mode when the page first opens.
 */
let selectedTravelMode = 'driving';


    /*
     * Keep track of the user's marker.
     */
    let userMarker = null;


    /*
     * Prevent the first GPS update from recreating
     * the routing interface repeatedly.
     */
    let isFirstUpdate = true;


    /*
     * Store the user's latest coordinates.
     *
     * This will also be useful when we add transportation
     * mode switching later.
     */
    let userLocation = null;


    // ================= ROUTE CREATION =================

/*
 * Routing configuration for each supported
 * transportation mode.
 *
 * Each mode uses its own routing server/profile.
 */
const routeModeConfig = {

    walking: {
        serviceUrl:
            'https://routing.openstreetmap.de/routed-foot/route/v1',

        profile: 'foot',

        name: 'Walking',

        icon: 'ph-person-simple-walk'
    },

    cycling: {
        serviceUrl:
            'https://routing.openstreetmap.de/routed-bike/route/v1',

        profile: 'cycling',

        name: 'Bicycle',

        icon: 'ph-bicycle'
    },

    driving: {
        serviceUrl:
            'https://routing.openstreetmap.de/routed-car/route/v1',

        profile: 'driving',

        name: 'Car',

        icon: 'ph-car'
    }

};

// ================= ROUTE BUTTON HINT =================

/*
 * Get the contextual route hint and the elements
 * inside it that display the selected transportation mode.
 */
const routeHint =
    document.getElementById('routeHint');

const routeHintIcon =
    document.getElementById('routeHintIcon');

const routeHintTitle =
    document.getElementById('routeHintTitle');

const routeHintSubtitle =
    document.getElementById('routeHintSubtitle');


/*
 * Store the timer used to automatically hide
 * the contextual hint.
 */
let routeHintTimeout = null;


/*
 * Show the contextual route hint.
 *
 * This appears after the user changes transportation
 * mode and explains that the route button opens
 * directions for that mode.
 */
function showRouteHint(mode) {

    /*
     * Find the configuration for the selected mode.
     */
    const config =
        routeModeConfig[mode];


    /*
     * Stop safely if the configuration or
     * required HTML elements do not exist.
     */
    if (
        !config ||
        !routeHint ||
        !routeHintIcon ||
        !routeHintTitle ||
        !routeHintSubtitle
    ) {
        return;
    }


    /*
     * Change the icon to match the selected
     * transportation mode.
     *
     * Example:
     * walking → walking icon
     * cycling → bicycle icon
     * driving → car icon
     */
    routeHintIcon.className =
        `ph-light ${config.icon}`;


    /*
     * Tell the user which route is available.
     */
    /*
 * Find the currently selected travel-time card.
 */
const selectedModeElement =
    document.querySelector(
        `.travel-mode[data-mode="${mode}"]`
    );


/*
 * Read the ETA currently displayed
 * for the selected transportation mode.
 */
const selectedTimeElement =
    selectedModeElement?.querySelector(
        '.travel-mode-time'
    );


/*
 * Use the displayed ETA if it is available.
 */
const selectedTime =
    selectedTimeElement?.textContent || '';


/*
 * Show the transportation mode and ETA together.
 */
routeHintTitle.textContent =
    selectedTime &&
    selectedTime !== 'Calculating...' &&
    selectedTime !== 'Unavailable'
        ? `${config.name} · ${selectedTime}`
        : `${config.name} route`;


/*
 * Tell the user exactly what happens
 * when they tap the hint.
 */
routeHintSubtitle.textContent =
    'Tap to view directions';


    /*
     * Cancel the previous automatic hide timer.
     */
    clearTimeout(routeHintTimeout);


    /*
     * Make the hint keyboard accessible.
     */
    routeHint.setAttribute(
        'tabindex',
        '0'
    );


    /*
     * Show the hint.
     *
     * CSS handles the smooth expansion animation.
     */
    routeHint.classList.add('active');


    /*
     * Automatically hide the hint after
     * four seconds.
     */
    routeHintTimeout = setTimeout(() => {

        hideRouteHint();

    }, 4000);
}


/*
 * Hide the contextual route hint safely.
 */
function hideRouteHint() {

    /*
     * Cancel the automatic hide timer.
     */
    clearTimeout(routeHintTimeout);


    /*
     * If the user currently has focus on the hint,
     * remove that focus before hiding the button.
     *
     * This prevents the browser's aria-hidden/focus
     * accessibility warning.
     */
    if (document.activeElement === routeHint) {

        routeHint.blur();

    }


    /*
     * Hide the hint.
     */
    routeHint.classList.remove('active');


    /*
     * Prevent keyboard navigation from reaching
     * the hidden hint.
     */
    routeHint.setAttribute(
        'tabindex',
        '-1'
    );
}

// ================= DIRECTIONS HEADER =================

/*
 * Update the Directions modal so it always reflects
 * the transportation mode currently selected.
 */
function updateDirectionsHeader(mode, summary = 'Calculating route...') {

    /*
     * Get the routing configuration for the selected mode.
     */
    const config = routeModeConfig[mode];

    if (!config) {
        return;
    }


    /*
     * Find the header elements.
     */
    const iconContainer =
        document.getElementById('routeModeIcon');

    const nameElement =
        document.getElementById('routeModeName');

    const summaryElement =
        document.getElementById('routeModeSummary');


    /*
     * Stop safely if the header does not exist.
     */
    if (
        !iconContainer ||
        !nameElement ||
        !summaryElement
    ) {
        return;
    }


    /*
     * Replace the transportation icon.
     */
    iconContainer.innerHTML =
        `<i class="ph-light ${config.icon}"></i>`;


    /*
     * Update the mode name.
     */
    nameElement.textContent =
        `${config.name} directions`;


    /*
     * Update the route summary.
     */
    summaryElement.textContent =
        summary;


    /*
     * Give the header a small visual refresh.
     */
    iconContainer.classList.remove('route-mode-change');

    void iconContainer.offsetWidth;

    iconContainer.classList.add('route-mode-change');
}


/*
 * Create the detailed route for the selected
 * transportation mode.
 */
function createRoute(userLat, userLng, mode = selectedTravelMode) {

    /*
     * Find the routing configuration for the
     * requested transportation mode.
     */
    const config = routeModeConfig[mode];


    /*
     * Stop if an unsupported mode is somehow requested.
     */
    if (!config) {
        console.error('Unsupported travel mode:', mode);
        return;
    }


    /*
     * Remove the existing routing control before
     * creating another one.
     *
     * This prevents multiple route controls from
     * simultaneously requesting routes.
     */
    if (routingControl) {

        navMap.removeControl(routingControl);

        routingControl = null;
    }


    /*
     * Clear the old directions panel.
     *
     * Otherwise, the previous mode's instructions
     * could remain visible in the modal.
     */
    const routeContainer =
        document.getElementById('routeContainer');

    if (routeContainer) {
        routeContainer.innerHTML = '';
    }


    /*
     * Create a new Leaflet Routing Machine control
     * using the selected transportation profile.
     */
    routingControl = L.Routing.control({

        /*
         * Starting point:
         * the user's current GPS position.
         *
         * Destination:
         * the agency's coordinates.
         */
        waypoints: [

            L.latLng(
                userLat,
                userLng
            ),

            L.latLng(
                lat,
                lng
            )

        ],

        /*
         * Prevent users from adding extra
         * waypoints to the route.
         */
        addWaypoints: false,

        /*
         * Prevent dragging the route endpoints.
         */
        draggableWaypoints: false,
        showAlternatives: false,


        /*
         * Use the routing server associated
         * with the selected transportation mode.
         */
        router: L.Routing.osrmv1({

            serviceUrl:
                config.serviceUrl,

            profile:
                config.profile

        }),


        /*
         * Keep the same visual route style
         * already used by KNOWURLOCAL.
         */
        lineOptions: {

            styles: [{

                color: '#7c3aed',

                weight: 6,

                opacity: 0.9

            }]

        },


        /*
         * We already have our own user and
         * destination markers, so LRM should
         * not create additional markers.
         */
        createMarker: () => null

    }).addTo(navMap);


    /*
     * Get the exact directions panel created by
     * this routing control.
     */
    const panel =
        routingControl.getContainer();


    /*
     * Get our custom Directions container.
     */
    const container =
        document.getElementById('routeContainer');


    /*
     * Move the directions panel immediately
     * into our custom container.
     *
     * This prevents it from briefly appearing
     * directly on the map.
     */
    if (
        panel &&
        container &&
        !container.contains(panel)
    ) {
        container.appendChild(panel);
    }


    /*
     * Listen for the routing result so we can show
     * the selected mode's distance and duration
     * in the Directions header.
     */
    routingControl.on(
    'routesfound',
    event => {

        /*
         * Take the primary route returned by
         * the routing service.
         */
        const route =
            event.routes?.[0];


        /*
         * Stop if no route was returned.
         */
        if (!route) {
            return;
        }

        /*
 * Save the coordinates of the currently selected
 * route so the destination label can detect
 * where the route passes near the agency marker.
 */
currentRouteCoordinates =
    route.coordinates || [];


/*
 * Wait until Leaflet has finished drawing the
 * route before measuring the label.
 */
requestAnimationFrame(() => {

    repositionDestinationLabel();

});

        queueMicrotask(() => {

    if (routingControl) {

        routingControl.setAlternatives([
            route
        ]);

    }

});

/*
 * Leaflet has now created the itinerary rows.
 *
 * Wait one browser frame so the generated
 * <tr> elements definitely exist before
 * attaching our click behavior.
 */
requestAnimationFrame(() => {

    attachDirectionClickHandlers();

});


        /*
         * Leaflet Routing Machine automatically
         * renders every returned route after
         * this event finishes.
         *
         * Queue our correction as a microtask so
         * it runs immediately after LRM finishes
         * rendering its alternatives, but before
         * the browser paints the next frame.
         */
        queueMicrotask(() => {

            if (routingControl) {

                routingControl.setAlternatives([
                    route
                ]);

            }

        });


        const distance =
            route.summary?.totalDistance;

        const time =
            route.summary?.totalTime;


        /*
         * Convert meters into a readable distance.
         */
        let distanceText = '';

        if (Number.isFinite(distance)) {

            if (distance >= 1000) {

                distanceText =
                    `${(distance / 1000).toFixed(1)} km`;

            } else {

                distanceText =
                    `${Math.round(distance)} m`;

            }
        }


        /*
         * Convert seconds into a readable duration.
         */
        const timeText =
            formatTravelTime(time);


        /*
         * Combine the values.
         */
        const summary =
            distanceText && timeText
                ? `${timeText} · ${distanceText}`
                : timeText;


        /*
         * Update the Directions header.
         */
        updateDirectionsHeader(
            selectedTravelMode,
            summary
        );

    }
);


    /*
     * Leaflet Routing Machine creates its
     * directions panel asynchronously.
     *
     * Wait briefly before moving it into
     * our custom modal.
     */
    

}

    // ================= ROUTE UPDATE =================

    /*
     * Update the existing route instead of creating
     * another routing control every time GPS changes.
     */
    function updateRoute(userLat, userLng) {

        /*
         * Nothing to update if routing has not been
         * initialized yet.
         */
        if (!routingControl) return;


        routingControl.setWaypoints([
            L.latLng(userLat, userLng),
            L.latLng(lat, lng)
        ]);
    }


    // ================= TRAVEL TIME =================

/*
 * Routing endpoints for the three transportation modes
 * supported by the routing server.
 *
 * These URLs are hardcoded rather than built from user input,
 * which prevents users from controlling the destination host.
 */
const travelModeConfig = {
    walking: {
        serviceUrl: 'https://routing.openstreetmap.de/routed-foot/route/v1',
        profile: 'foot'
    },

    cycling: {
        serviceUrl: 'https://routing.openstreetmap.de/routed-bike/route/v1',
        profile: 'cycling'
    },

    driving: {
        serviceUrl: 'https://routing.openstreetmap.de/routed-car/route/v1',
        profile: 'driving'
    }
};


/*
 * Keep track of the last location used for ETA calculation.
 *
 * This prevents us from sending a new request every time
 * the browser reports a tiny GPS movement.
 */
let lastEtaLocation = null;


/*
 * Prevent multiple ETA requests from running at the same time.
 */
let etaRequestInProgress = false;


/*
 * Only refresh the travel times after the user has moved
 * a meaningful distance.
 */
const ETA_MIN_DISTANCE = 100;


/*
 * Calculate the distance between two geographic coordinates.
 *
 * This uses the Haversine formula, which is appropriate
 * for calculating the straight-line distance between
 * two latitude/longitude points.
 */
function calculateDistance(lat1, lng1, lat2, lng2) {

    const earthRadius = 6371000;

    const latDifference =
        (lat2 - lat1) * Math.PI / 180;

    const lngDifference =
        (lng2 - lng1) * Math.PI / 180;

    const a =
        Math.sin(latDifference / 2) ** 2 +
        Math.cos(lat1 * Math.PI / 180) *
        Math.cos(lat2 * Math.PI / 180) *
        Math.sin(lngDifference / 2) ** 2;

    const c =
        2 * Math.atan2(
            Math.sqrt(a),
            Math.sqrt(1 - a)
        );

    return earthRadius * c;
}


/*
 * Convert the routing server's duration in seconds
 * into a readable value for the interface.
 */
function formatTravelTime(seconds) {

    if (!Number.isFinite(seconds) || seconds < 0) {
        return 'Unavailable';
    }

    const minutes = Math.round(seconds / 60);

    if (minutes < 1) {
        return '<1 min';
    }

    if (minutes === 1) {
        return '1 min';
    }

    if (minutes < 60) {
        return `${minutes} min`;
    }

    const hours = Math.floor(minutes / 60);
    const remainingMinutes = minutes % 60;

    if (remainingMinutes === 0) {
        return `${hours} hr`;
    }

    return `${hours} hr ${remainingMinutes} min`;
}


/*
 * Update one travel-time card.
 *
 * The mode determines which routing service is requested.
 */
async function updateTravelMode(mode, userLat, userLng) {

    const config = travelModeConfig[mode];

    if (!config) {
        console.error('Unknown travel mode:', mode);
        return;
    }


    /*
     * Find the corresponding card in the HTML.
     */
    const modeElement = document.querySelector(
        `.travel-mode[data-mode="${mode}"]`
    );

    if (!modeElement) {
        return;
    }


    /*
     * Find the element where the ETA will be displayed.
     */
    const timeElement =
        modeElement.querySelector('.travel-mode-time');

    if (!timeElement) {
        return;
    }


    /*
     * Show a loading state while the server calculates
     * the route.
     */
    timeElement.textContent = 'Calculating...';
    timeElement.classList.add('loading');


    /*
     * OSRM expects coordinates in LONGITUDE,LATITUDE order.
     *
     * This is different from Leaflet's LATITUDE,LONGITUDE
     * convention, so the order here is intentional.
     */
    const coordinates =
        `${userLng},${userLat};${lng},${lat}`;


    /*
     * Build the route request using only our fixed
     * routing server and validated coordinates.
     */
    const url =
        `${config.serviceUrl}/${config.profile}/${coordinates}` +
        '?overview=false&steps=false';


    try {

        /*
         * Abort requests that take too long.
         *
         * This prevents a slow external routing server
         * from leaving the UI stuck indefinitely.
         */
        const controller = new AbortController();

        const timeout = setTimeout(
    () => controller.abort(),
    15000
);


        /*
         * Request the route from the selected routing service.
         */
        const response = await fetch(
            url,
            {
                method: 'GET',
                signal: controller.signal,
                headers: {
                    'Accept': 'application/json'
                }
            }
        );


        /*
         * Stop the timeout once the request finishes.
         */
        clearTimeout(timeout);


        /*
         * Reject HTTP errors instead of trying to process
         * an invalid response.
         */
        if (!response.ok) {
            throw new Error(
                `Routing request failed: ${response.status}`
            );
        }


        /*
         * Parse the JSON response.
         */
        const data = await response.json();


        /*
         * OSRM returns the calculated routes inside
         * the "routes" array.
         */
        const route = data.routes?.[0];


        if (!route) {
            throw new Error('No route returned.');
        }


        /*
 * Convert the returned route duration into the
 * same human-readable format used by the travel
 * time card.
 */
const formattedTime =
    formatTravelTime(route.duration);


/*
 * Display the calculated ETA in the travel-mode
 * card.
 */
timeElement.textContent =
    formattedTime;


/*
 * Remove the loading state because this mode
 * now has a valid result.
 */
timeElement.classList.remove('loading');


/*
 * The default transportation mode should introduce
 * the Directions button as soon as its ETA becomes
 * available.
 *
 * This is intentionally triggered only after a
 * successful routing response, so the user never
 * sees a "View route" hint while the ETA is still
 * calculating.
 */
if (
    mode === selectedTravelMode &&
    formattedTime !== 'Unavailable'
) {

    showRouteHint(mode);

}


    } catch (error) {

    /*
     * AbortError means our timeout cancelled
     * the request.
     */
    if (error.name === 'AbortError') {

        console.warn(
            `Travel time request timed out for ${mode}.`
        );

    } else {

        console.error(
            `Travel time request failed for ${mode}:`,
            error
        );

    }

    timeElement.textContent = 'Unavailable';

    timeElement.classList.remove('loading');
}
}


/*
 * Update all three transportation modes.
 */
async function updateTravelTimes(userLat, userLng) {

    /*
     * Prevent duplicate requests from overlapping.
     */
    if (etaRequestInProgress) {
        return;
    }


    /*
     * If we already have a previous GPS location,
     * check whether the user actually moved enough.
     */
    if (lastEtaLocation) {

        const distance = calculateDistance(
            lastEtaLocation.lat,
            lastEtaLocation.lng,
            userLat,
            userLng
        );


        /*
         * Skip the request if the movement was too small.
         */
        if (distance < ETA_MIN_DISTANCE) {
            return;
        }
    }


    /*
     * Remember this location as the latest ETA location.
     */
    lastEtaLocation = {
        lat: userLat,
        lng: userLng
    };


    etaRequestInProgress = true;


    try {

        /*
         * Run the three independent routing requests together.
         *
         * This is faster than waiting for one request to finish
         * before starting the next one.
         * 
         * 
         */

        /*
 * Pause between requests.
 *
 * The public routing server recommends a maximum
 * of one request per second, so we intentionally
 * wait slightly longer than one second.
 */
function wait(milliseconds) {

    return new Promise(resolve => {
        setTimeout(resolve, milliseconds);
    });

}

        await updateTravelMode(
    'walking',
    userLat,
    userLng
);

await wait(1100);

await updateTravelMode(
    'cycling',
    userLat,
    userLng
);

await wait(1100);

await updateTravelMode(
    'driving',
    userLat,
    userLng
);

    } finally {

        /*
         * Allow another ETA update after this batch finishes.
         */
        etaRequestInProgress = false;
    }
}


// ================= TRAVEL MODE SELECTION =================

/*
 * Find every transportation card in the travel-time
 * component.
 */
const travelModeElements =
    document.querySelectorAll('.travel-mode');


/*
 * Update the visual state of the transportation cards.
 */
function updateTravelModeUI(mode) {

    /*
     * Loop through every available transportation card.
     */
    travelModeElements.forEach(element => {

        /*
         * Determine whether this card represents
         * the currently selected mode.
         */
        const isActive =
            element.dataset.mode === mode;


        /*
         * Add or remove the visual active state.
         */
        element.classList.toggle(
            'active',
            isActive
        );


        /*
         * Update accessibility information.
         */
        element.setAttribute(
            'aria-pressed',
            isActive ? 'true' : 'false'
        );

    });

}


/*
 * Select a transportation mode.
 */
function selectTravelMode(mode) {

    /*
     * Make sure the requested mode actually exists
     * in our routing configuration.
     */
    if (!routeModeConfig[mode]) {
        return;
    }


    /*
     * Do nothing if the user clicks the mode
     * that is already selected.
     */
    if (selectedTravelMode === mode) {
        return;
    }


    /*
     * Remember the newly selected mode.
     */
    selectedTravelMode = mode;


    /*
     * Update the card appearance.
     */
    updateTravelModeUI(mode);
    updateDirectionsHeader(mode);
    showRouteHint(mode);


    /*
     * We need the user's current location before
     * we can create a new route.
     */
    if (!userLocation) {
        return;
    }


    /*
     * Recreate the detailed route using
     * the selected transportation mode.
     */
    createRoute(
        userLocation.lat,
        userLocation.lng,
        selectedTravelMode
    );

}


/*
 * Attach interaction to every transportation card.
 */
travelModeElements.forEach(element => {

    /*
     * Mouse/touch interaction.
     */
    element.addEventListener(
        'click',
        () => {

            selectTravelMode(
                element.dataset.mode
            );

        }
    );


    /*
     * Keyboard interaction.
     *
     * Enter and Space behave like clicking
     * the transportation card.
     */
    element.addEventListener(
        'keydown',
        event => {

            if (
                event.key === 'Enter' ||
                event.key === ' '
            ) {

                event.preventDefault();

                selectTravelMode(
                    element.dataset.mode
                );

            }

        }
    );

});


/*
 * Car is the initial/default transportation mode.
 */
updateTravelModeUI(
    selectedTravelMode
);

    // ================= GPS =================

    /*
     * Watch the user's position continuously.
     *
     * This allows the route to react when the user moves.
     */
    navigator.geolocation.watchPosition(

        function (pos) {

            /*
             * Extract the coordinates returned by
             * the browser's Geolocation API.
             */
            const userLat = pos.coords.latitude;
            const userLng = pos.coords.longitude;


            /*
             * Save the latest position.
             */
            userLocation = {
                lat: userLat,
                lng: userLng
            };

            /*
 * Calculate the travel times using the user's
 * current GPS position.
 */
updateTravelTimes(
    userLat,
    userLng
);


            // ================= FIRST GPS UPDATE =================

            if (isFirstUpdate) {

                /*
                 * Create the user's location marker.
                 */
                userMarker = L.marker(
                    [userLat, userLng],
                    { icon: userIcon }
                ).addTo(navMap);


                /*
                 * Move the map toward the user's location.
                 */
                navMap.flyTo(
                    [userLat, userLng],
                    16,
                    {
                        animate: true,
                        duration: 1.5
                    }
                );


                /*
                 * Create the initial route.
                 */
                createRoute(
                    userLat,
                    userLng
                );


                /*
                 * Prevent another routing control
                 * from being created on the next update.
                 */
                isFirstUpdate = false;

                return;
            }


            // ================= SUBSEQUENT GPS UPDATES =================

            /*
             * Move the existing user marker.
             */
            if (userMarker) {
                userMarker.setLatLng([
                    userLat,
                    userLng
                ]);
            }


            /*
             * Update the existing route.
             */
            updateRoute(
                userLat,
                userLng
            );

        },

        function (error) {

            /*
             * Do not expose technical GPS error details
             * directly to the user.
             */
            console.error(
                'Geolocation error:',
                error.code
            );

            alert(
                'Unable to access your location. Please enable GPS/location permission and try again.'
            );
        },

        {
            /*
             * Request the most accurate position available.
             */
            enableHighAccuracy: true,

            /*
             * Do not accept an indefinitely old location.
             */
            maximumAge: 5000,

            /*
             * Give the browser a reasonable amount of
             * time to obtain the position.
             */
            timeout: 10000
        }
    );

    // ================= CLOSE MODAL AFTER DIRECTION CLICK =================

/*
 * Attach our own click behavior to Leaflet's
 * individual direction rows.
 *
 * Leaflet creates these rows dynamically after
 * the routing request finishes, so they cannot
 * be selected reliably during initial page load.
 */
function attachDirectionClickHandlers() {

    /*
     * Find every individual instruction row
     * generated by Leaflet Routing Machine.
     *
     * Leaflet's default ItineraryBuilder creates
     * each instruction as a <tr>.
     */
    const directionRows =
        document.querySelectorAll(
            '#routeContainer .leaflet-routing-alt tr'
        );


    /*
     * Attach the behavior to every direction row.
     */
    directionRows.forEach(row => {

        /*
         * Prevent attaching the same listener
         * more than once if the route is rebuilt.
         */
        if (
            row.dataset.modalCloseAttached === 'true'
        ) {
            return;
        }


        /*
         * Mark this row as already processed.
         */
        row.dataset.modalCloseAttached = 'true';


        /*
         * Listen directly on the row.
         *
         * This is important because Leaflet's own
         * handler stops the event from bubbling.
         */
        row.addEventListener(
            'click',
            () => {

                /*
                 * Give Leaflet a moment to execute
                 * its own click handler, which pans
                 * the map to the selected instruction.
                 */
                setTimeout(() => {

                    if (modal) {

                        modal.classList.remove(
                            'active'
                        );

                    }

                }, 0);

            }
        );

    });

}

    // ================= DIRECTIONS MODAL =================

    const modal = document.getElementById('routeModal');
    const openBtn = document.getElementById('openRoute');
    const closeBtn = document.getElementById('closeRoute');


    /*
     * Only attach modal behavior when all required
     * elements exist.
     */
    if (modal && openBtn && closeBtn) {

        /*
        * Clicking the contextual route hint opens
        * the same Directions modal.
        */

        if (routeHint) {

            routeHint.addEventListener(
                'click',
                () => {

                    /*
                    * Open the Directions modal.
                    */
                    modal.classList.add('active');


                    /*
                    * Hide the contextual hint after
                    * the user has used it.
                    */
                    hideRouteHint();

                }
            );

        }

        /*
         * Open directions.
         */
        openBtn.addEventListener(
            'click',
            () => {
                modal.classList.add('active');
            }
        );


        /*
         * Close directions.
         */
        closeBtn.addEventListener(
            'click',
            () => {
                modal.classList.remove('active');
            }
        );


        /*
         * Allow clicking the backdrop to close
         * the directions panel.
         */
        modal.addEventListener(
            'click',
            (event) => {

                if (event.target === modal) {
                    modal.classList.remove('active');
                }

            }
        );

        

    }

}); 